{
  "hazard_consequence_node": {
    "label": "HazardConsequence",
    "name": "Dust explosion",
    "node_id": "H1",
    "node_type": "HazardConsequence",
    "evidence": "The Executive Summary states: \"A February 20, 2003, dust explosion at the CTA Acoustics, Inc. facility in Corbin, Kentucky, killed seven and injured 37 workers.\" It also states that \"combustible phenolic resin dust that had accumulated throughout the facility fueled the explosion.\" The incident description further says that the initial explosion and later secondary explosions were caused when dispersed combustible dust ignited.",
    "explanation": "The report’s main analysis centers on combustible phenolic resin dust accumulation, dispersion during cleaning, ignition near line 405, and propagation into secondary dust explosions across the facility. This makes dust explosion the primary hazard consequence, while fires, fireballs, and confined effects are escalation phenomena within the same dust-explosion event sequence.",
    "source": "incident_description"
  },
  "explanation": {
    "reasoning": "Dust explosion is the primary hazard consequence because the report repeatedly identifies the event as a dust explosion, attributes the fatalities and damage to combustible dust ignition and propagation, and focuses its root-cause analysis on combustible dust accumulation, housekeeping, maintenance, and explosion prevention.",
    "excluded_alternatives": [
      {
        "label": "VCE",
        "reason": "No vapor cloud release of flammable gas or vapor was identified as the main mechanism; natural gas was specifically investigated and ruled out."
      },
      {
        "label": "BLEVE",
        "reason": "There was no boiling liquid expanding vapor explosion involving a pressurized vessel containing liquefied gas."
      },
      {
        "label": "Confined explosion",
        "reason": "Some secondary explosions occurred in confined areas above blend rooms, but these were secondary manifestations of the broader combustible dust explosion scenario rather than the main incident type."
      },
      {
        "label": "Pool fire",
        "reason": "There was no burning liquid pool as the central event."
      },
      {
        "label": "Jet fire",
        "reason": "There was no sustained pressurized release producing a jet flame."
      },
      {
        "label": "Fire ball",
        "reason": "Witnesses described fireballs, but these were effects of the dust explosions and flame propagation, not the primary accident mechanism analyzed."
      },
      {
        "label": "Flash fire",
        "reason": "Although flame spread occurred through dispersed combustibles, the report emphasizes explosion overpressure and combustible dust explosibility rather than a non-overpressure flash fire."
      },
      {
        "label": "Toxicity dispersion",
        "reason": "Potential toxic combustion products prompted evacuation, but air monitoring found no toxic levels and toxic release was not the main incident consequence analyzed."
      },
      {
        "label": "Asphyxiation",
        "reason": "The injuries and fatalities were due to burns and explosion effects, not oxygen deficiency or inert gas displacement."
      }
    ]
  }
}
